<?php
declare(strict_types=1);

require_once __DIR__.'/includes/init.php';
require_once __DIR__.'/csrf_helper.php';
require_once __DIR__.'/includes/shop_member_pricing.php';

if (!isset($_SESSION['trener_id']) || !roleAtLeast('admin')) {header('Location: login.php');exit;}
function memberPriceH(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function memberPriceDecimal(string $value):int{
    $value=str_replace([' ', ','],['','.'],trim($value));
    if(preg_match('/^\d{1,9}(?:\.\d{1,2})?$/D',$value)!==1)throw new InvalidArgumentException('Částka musí být nezáporné číslo s nejvýše dvěma desetinnými místy.');
    [$whole,$decimal]=array_pad(explode('.',$value,2),2,'');return (int)$whole*100+(int)str_pad($decimal,2,'0');
}
function memberPricePercent(string $value):int{
    $value=str_replace(',','.',trim($value));if(preg_match('/^\d{1,3}(?:\.\d{1,2})?$/D',$value)!==1)throw new InvalidArgumentException('Procento musí být číslo s nejvýše dvěma desetinnými místy.');
    return (int)round((float)$value*100);
}
$teams=$pdo->query("SELECT t.id,t.name,s.name AS season_name FROM club_teams t JOIN club_seasons s ON s.id=t.season_id WHERE t.status='active' ORDER BY s.starts_on DESC,t.name")->fetchAll(PDO::FETCH_ASSOC);
$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!csrf_verify((string)($_POST['csrf_token']??'')))$errors[]='Formulář vypršel. Obnovte stránku.';
    else try{
        $action=(string)($_POST['action']??'');$actor=(int)$_SESSION['trener_id'];$note=(string)($_POST['note']??'');
        if(in_array($action,['category','product'],true)&&$teams===[])throw new ShopMemberPricingException('Klubovou cenu nelze založit bez aktivní soupisky. Nejprve požádejte správce členství o založení soupisky.');
        if($action==='category'){
            $type=(string)($_POST['discount_type']??'');$raw=(string)($_POST['value']??'');
            $value=$type==='percentage'?memberPricePercent($raw):memberPriceDecimal($raw);
            shopMemberPricingSetCategoryRule($pdo,(int)($_POST['team_id']??0),(string)($_POST['category_path']??''),$type,$value,$type==='fixed_discount'?'CZK':null,$actor,$note);
        }elseif($action==='product'){
            shopMemberPricingSetProductPrice($pdo,(int)($_POST['team_id']??0),(int)($_POST['product_id']??0),memberPriceDecimal((string)($_POST['amount']??'')),'CZK',$actor,$note);
        }elseif($action==='deactivate')shopMemberPricingDeactivate($pdo,(string)($_POST['kind']??''),(int)($_POST['rule_id']??0),$actor,$note);
        else throw new InvalidArgumentException('Neplatná akce.');
        $_SESSION['flash_member_price']='Klubové cenové pravidlo bylo bezpečně uloženo.';header('Location: eshop_member_prices_admin.php',true,303);exit;
    }catch(PDOException$e){error_log('eshop_member_prices_admin.php: '.$e->getMessage());$errors[]='Databázová operace selhala bez částečné změny.';}catch(InvalidArgumentException|ShopMemberPricingException$e){$errors[]=$e->getMessage();}
}
$success=(string)($_SESSION['flash_member_price']??'');unset($_SESSION['flash_member_price']);
$categories=$pdo->query('SELECT DISTINCT category_path FROM shop_product_categories ORDER BY category_path')->fetchAll(PDO::FETCH_COLUMN);
$products=$pdo->query("SELECT p.id,COALESCE(pub.public_name,p.name) AS name FROM shop_products p LEFT JOIN shop_product_publications pub ON pub.product_id=p.id WHERE p.catalog_status='active' ORDER BY name")->fetchAll(PDO::FETCH_ASSOC);
$categoryRules=$pdo->query('SELECT r.*,t.name AS team_name FROM shop_member_category_rules r JOIN club_teams t ON t.id=r.team_id ORDER BY r.active DESC,t.name,r.category_path')->fetchAll(PDO::FETCH_ASSOC);
$productRules=$pdo->query('SELECT r.*,t.name AS team_name,COALESCE(pub.public_name,p.name) AS product_name FROM shop_member_product_prices r JOIN club_teams t ON t.id=r.team_id JOIN shop_products p ON p.id=r.product_id LEFT JOIN shop_product_publications pub ON pub.product_id=p.id ORDER BY r.active DESC,t.name,product_name')->fetchAll(PDO::FETCH_ASSOC);
$events=$pdo->query('SELECT e.*,t.name AS team_name,tr.jmeno AS actor_name FROM shop_member_price_events e JOIN club_teams t ON t.id=e.team_id JOIN treneri tr ON tr.id=e.actor_trainer_id ORDER BY e.id DESC LIMIT 100')->fetchAll(PDO::FETCH_ASSOC);
$preselected=(int)($_GET['product_id']??0);
?>
